-- PostgreSQL / Supabase. Bản chuyển từ schema MySQL cũ, giữ nguyên tên bảng, tên cột, ràng buộc.
-- Cloud: database đã được nhà cung cấp tạo sẵn, chọn database qua DATABASE_URL.
-- Không dùng CREATE DATABASE / USE ở đây.
-- Thay đổi cấu trúc về sau: viết thành file trong db/migrations/ (001_..., 002_...).
--
-- Khác biệt so với bản MySQL (đều là hệ quả của việc đổi engine, không đổi nghiệp vụ):
--   INT UNSIGNED AUTO_INCREMENT  → INTEGER GENERATED BY DEFAULT AS IDENTITY (cho phép seed chèn id tay)
--   ENUM(...)                    → VARCHAR + CHECK (dễ ALTER hơn kiểu ENUM của Postgres)
--   DATETIME                     → TIMESTAMPTZ
--   ON UPDATE CURRENT_TIMESTAMP  → trigger set_updated_at()
--   COLLATE ..._ci (không phân biệt hoa thường) → email so sánh bằng lower(email)

CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- 1. users ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS users (
    user_id       INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    full_name     VARCHAR(100) NOT NULL,
    email         VARCHAR(255) NOT NULL,
    password_hash VARCHAR(255) NULL,
    auth_provider VARCHAR(10)  NOT NULL CHECK (auth_provider IN ('LOCAL', 'GOOGLE')),
    user_role     VARCHAR(10)  NOT NULL CHECK (user_role IN ('admin', 'tester', 'dev', 'viewer')),
    user_status   VARCHAR(10)  NOT NULL DEFAULT 'active' CHECK (user_status IN ('active', 'inactive')),
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now()
);
-- Email không phân biệt hoa thường như collation _ci cũ.
CREATE UNIQUE INDEX IF NOT EXISTS uq_users_email ON users (lower(email));


-- 2. test_suites ------------------------------------------------------
CREATE TABLE IF NOT EXISTS test_suites (
    suite_id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    suite_name        VARCHAR(150) NOT NULL,
    suite_description TEXT NULL,
    created_by        INTEGER NULL,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by        INTEGER NULL,
    updated_at        TIMESTAMPTZ NULL DEFAULT NULL,
    CONSTRAINT fk_suites_created_by FOREIGN KEY (created_by) REFERENCES users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_suites_updated_by FOREIGN KEY (updated_by) REFERENCES users(user_id) ON DELETE SET NULL
);


-- 3. test_specs -------------------------------------------------------
CREATE TABLE IF NOT EXISTS test_specs (
    spec_id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    spec_code        VARCHAR(30) NOT NULL,
    suite_id         INTEGER NOT NULL,
    source_reference VARCHAR(255) NULL,
    screen_name      VARCHAR(255) NULL,
    spec_description TEXT NULL,
    created_by       INTEGER NULL,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by       INTEGER NULL,
    updated_at       TIMESTAMPTZ NULL DEFAULT NULL,
    CONSTRAINT uq_specs_spec_code UNIQUE (spec_code),
    CONSTRAINT fk_specs_suite      FOREIGN KEY (suite_id)   REFERENCES test_suites (suite_id) ON DELETE RESTRICT,
    CONSTRAINT fk_specs_created_by FOREIGN KEY (created_by) REFERENCES users (user_id)        ON DELETE SET NULL,
    CONSTRAINT fk_specs_updated_by FOREIGN KEY (updated_by) REFERENCES users (user_id)        ON DELETE SET NULL
);


-- 4. test_cases -------------------------------------------------------
CREATE TABLE IF NOT EXISTS test_cases (
    test_id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    execution_status VARCHAR(15) NOT NULL DEFAULT 'pending'
                     CHECK (execution_status IN ('pending', 'in_progress', 'done', 'reopened')),
    spec_id          INTEGER NOT NULL,
    tc_code          VARCHAR(30)  NOT NULL,
    title            VARCHAR(255) NOT NULL,
    preconditions    TEXT NULL,
    expected_result  TEXT NOT NULL,
    priority         VARCHAR(10) NOT NULL CHECK (priority IN ('low', 'medium', 'high', 'critical')),
    test_type        VARCHAR(15) NOT NULL
                     CHECK (test_type IN ('functional', 'ui', 'validation', 'security', 'performance', 'usability', 'audit')),
    test_status      VARCHAR(15) NOT NULL DEFAULT 'draft' CHECK (test_status IN ('draft', 'ready', 'deprecated')),
    automation_ref   VARCHAR(255) NULL,
    created_by       INTEGER NULL,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by       INTEGER NULL,
    updated_at       TIMESTAMPTZ NULL DEFAULT NULL,
    CONSTRAINT uq_cases_tc_code        UNIQUE (tc_code),
    CONSTRAINT uq_cases_automation_ref UNIQUE (automation_ref),
    CONSTRAINT fk_cases_spec       FOREIGN KEY (spec_id)    REFERENCES test_specs(spec_id) ON DELETE RESTRICT,
    CONSTRAINT fk_cases_created_by FOREIGN KEY (created_by) REFERENCES users(user_id)      ON DELETE SET NULL,
    CONSTRAINT fk_cases_updated_by FOREIGN KEY (updated_by) REFERENCES users(user_id)      ON DELETE SET NULL
);


-- 5. test_steps -------------------------------------------------------
CREATE TABLE IF NOT EXISTS test_steps (
    step_id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    test_id         INTEGER NOT NULL,
    step_order      INTEGER NOT NULL CHECK (step_order >= 0),
    step_action     TEXT NOT NULL,
    step_target     VARCHAR(255) NULL,
    expected_result TEXT NULL,
    CONSTRAINT uq_steps_order UNIQUE (test_id, step_order),
    CONSTRAINT fk_steps_case FOREIGN KEY (test_id) REFERENCES test_cases(test_id) ON DELETE CASCADE
);


-- 6. test_data --------------------------------------------------------
CREATE TABLE IF NOT EXISTS test_data (
    data_id    INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    test_id    INTEGER NOT NULL,
    field_name VARCHAR(100) NOT NULL,
    data_value TEXT NULL,
    is_valid   BOOLEAN NOT NULL,
    CONSTRAINT fk_data_case FOREIGN KEY (test_id) REFERENCES test_cases(test_id) ON DELETE CASCADE
);


-- 7. test_runs --------------------------------------------------------
CREATE TABLE IF NOT EXISTS test_runs (
    run_id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    execution_type VARCHAR(10) NOT NULL DEFAULT 'automation' CHECK (execution_type IN ('automation', 'manual')), -- manual: frontend nhập, backend ghi vào db
    started_at     TIMESTAMPTZ NOT NULL,
    finished_at    TIMESTAMPTZ NULL,
    browser        VARCHAR(50) NOT NULL,
    environment    VARCHAR(100) NULL,
    git_commit     VARCHAR(64) NULL,
    branch_name    VARCHAR(100) NULL,
    ci_run_id      VARCHAR(100) NULL,
    tester_id      INTEGER NULL, -- user thực hiện lần chạy test
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT fk_test_runs_tester FOREIGN KEY (tester_id) REFERENCES users(user_id) ON DELETE SET NULL
);


-- 8. test_results -----------------------------------------------------
CREATE TABLE IF NOT EXISTS test_results (
    execution_id      INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    run_id            INTEGER NOT NULL,
    test_id           INTEGER NOT NULL,
    result_status     VARCHAR(15) NOT NULL
                      CHECK (result_status IN ('passed', 'failed', 'timedOut', 'skipped', 'interrupted')),
    actual_result     TEXT NULL, -- kết quả thực tế của test case
    execution_time_ms INTEGER NOT NULL DEFAULT 0 CHECK (execution_time_ms >= 0),
    error_message     TEXT NULL,
    retry_count       INTEGER NOT NULL DEFAULT 0 CHECK (retry_count >= 0),
    CONSTRAINT uq_results_run_execution UNIQUE (run_id, execution_id),
    CONSTRAINT fk_results_run  FOREIGN KEY (run_id)  REFERENCES test_runs(run_id)   ON DELETE CASCADE,
    CONSTRAINT fk_results_case FOREIGN KEY (test_id) REFERENCES test_cases(test_id) ON DELETE CASCADE
);


-- 9. test_evidences ---------------------------------------------------
CREATE TABLE IF NOT EXISTS test_evidences (
    evidence_id   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    result_id     INTEGER NOT NULL,
    evidence_type VARCHAR(15) NOT NULL CHECK (evidence_type IN ('screenshot', 'trace')),
    file_path     VARCHAR(500) NOT NULL,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT fk_evidences_result FOREIGN KEY (result_id) REFERENCES test_results(execution_id) ON DELETE CASCADE
);


-- 11. reports ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS reports (
    report_id    INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    run_id       INTEGER NOT NULL,
    execution_id INTEGER NOT NULL,
    report_type  VARCHAR(10) NOT NULL CHECK (report_type IN ('pdf')),
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT fk_reports_run    FOREIGN KEY (run_id)       REFERENCES test_runs(run_id)            ON DELETE CASCADE,
    CONSTRAINT fk_reports_result FOREIGN KEY (execution_id) REFERENCES test_results(execution_id)   ON DELETE CASCADE
);


-- Thay cho ON UPDATE CURRENT_TIMESTAMP của MySQL --------------------------
DROP TRIGGER IF EXISTS trg_test_suites_updated_at ON test_suites;
CREATE TRIGGER trg_test_suites_updated_at BEFORE UPDATE ON test_suites FOR EACH ROW EXECUTE FUNCTION set_updated_at();
DROP TRIGGER IF EXISTS trg_test_specs_updated_at ON test_specs;
CREATE TRIGGER trg_test_specs_updated_at BEFORE UPDATE ON test_specs FOR EACH ROW EXECUTE FUNCTION set_updated_at();
DROP TRIGGER IF EXISTS trg_test_cases_updated_at ON test_cases;
CREATE TRIGGER trg_test_cases_updated_at BEFORE UPDATE ON test_cases FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Update task A1 (
--   - Tạo bảng pages, items, page_items để mô tả các trang web và các thành phần UI cần test.
--   - Gắn trigger tự động cập nhật updated_at cho các bảng mới.
-- )
-- 1. Tạo bảng pages (Mô tả trang web để test)

-- 1. Tạo bảng pages (Mô tả trang web để test)
CREATE TABLE IF NOT EXISTS pages (
    page_id     INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title       VARCHAR(255) NOT NULL,
    url_path    VARCHAR(255) NOT NULL,
    use_status  VARCHAR(20)  NOT NULL DEFAULT 'draft' 
                CHECK (use_status IN ('disable', 'inactive', 'active', 'draft')),
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ  NULL DEFAULT NULL
);

-- 2. Tạo bảng items (Các thành phần UI như h1, button, table...)
CREATE TABLE IF NOT EXISTS items (
    item_id     INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(255) NOT NULL,
    tag_type    VARCHAR(100) NOT NULL,
    selector    VARCHAR(255) NULL,
    use_status  VARCHAR(20)  NOT NULL DEFAULT 'active' 
                CHECK (use_status IN ('disable', 'inactive', 'active', 'draft')),
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ  NULL DEFAULT NULL
);

-- 3. Tạo bảng trung gian page_items (Quan hệ *-* giữa Page và Item)
CREATE TABLE IF NOT EXISTS page_items (
    page_id     INTEGER NOT NULL,
    item_id     INTEGER NOT NULL,
    PRIMARY KEY (page_id, item_id),
    CONSTRAINT fk_page_items_page FOREIGN KEY (page_id) REFERENCES pages(page_id) ON DELETE CASCADE,
    CONSTRAINT fk_page_items_item FOREIGN KEY (item_id) REFERENCES items(item_id) ON DELETE CASCADE
);

-- 4. Gắn trigger tự động cập nhật updated_at (đồng bộ phong cách với các bảng cũ của tụi mày)
DROP TRIGGER IF EXISTS trg_pages_updated_at ON pages;
CREATE TRIGGER trg_pages_updated_at BEFORE UPDATE ON pages FOR EACH ROW EXECUTE FUNCTION set_updated_at();

DROP TRIGGER IF EXISTS trg_items_updated_at ON items;
CREATE TRIGGER trg_items_updated_at BEFORE UPDATE ON items FOR EACH ROW EXECUTE FUNCTION set_updated_at();

ALTER TABLE test_cases ADD COLUMN page_id INTEGER REFERENCES pages(page_id) ON DELETE SET NULL;
